// UTF-8 bytes are a conservative upper bound, not a model tokenizer or savings metric.
export const estimateTokens = (value: unknown): number =>
  Buffer.byteLength(JSON.stringify(value), "utf8");
export function optimize<T>(
  items: T[],
  budget: number,
): { memories: T[]; estimatedTokens: number; estimator: string } {
  const result = {
    memories: [] as T[],
    estimatedTokens: 0,
    estimator: "conservative UTF-8 byte upper bound; not model tokens",
  };
  for (const item of items) {
    const next = {
      ...result,
      memories: [...result.memories, item],
      estimatedTokens: budget,
    };
    if (estimateTokens({ ok: true, data: next }) <= budget)
      result.memories.push(item);
  }
  result.estimatedTokens = estimateTokens({
    ok: true,
    data: { ...result, estimatedTokens: budget },
  });
  return result;
}

if (op === "memory_search") {
  const start = performance.now();
  const rows = new FtsRetriever(this.db).search(
    d as unknown as RetrievalFilter,
  );
  const seen = new Set<string>();
  const result = optimize(
    rows
      .filter((m) => {
        if (seen.has(String(m.hash))) return false;
        seen.add(String(m.hash));
        return true;
      })
      .map((m) => this.view(m)),
    Number(d.tokenBudget),
  );
  this.storage.transaction(() => {
    const retrievalId = randomUUID();
    for (const m of result.memories)
      this.db
        .prepare("UPDATE memories SET uses=uses+1 WHERE id=?")
        .run(String(m.id));
    this.db
      .prepare("INSERT INTO retrievals VALUES(?,?,?,?,?,?)")
      .run(
        retrievalId,
        p,
        performance.now() - start,
        result.estimatedTokens,
        result.memories.length,
        new Date().toISOString(),
      );
    for (const m of result.memories)
      this.db
        .prepare("INSERT INTO retrieval_items VALUES(?,?)")
        .run(retrievalId, String(m.id));
  });
  return result;
}

if (op === "memory_stats")
  return {
    memories: this.db
      .prepare(
        "SELECT status,type,count(*) AS count,sum(uses) AS uses FROM memories WHERE project_id=? GROUP BY status,type",
      )
      .all(p),
    retrievals: this.db
      .prepare(
        "SELECT count(*) AS count,sum(tokens) AS estimatedTokens,avg(elapsed_ms) AS meanMs FROM retrievals WHERE project_id=?",
      )
      .get(p),
  };

if (op === "memory_feedback")
  return this.storage.transaction(() => {
    const m = this.managedMemory(p, id, d);
    if (
      d.scope === "global" &&
      (m.scope !== "global" ||
        !d.sharingApproval ||
        !["deprecate", "reject", "note"].includes(String(d.action)))
    )
      throw new AppError(
        "SHARING_APPROVAL_REQUIRED",
        "Only explicitly approved global deprecation, rejection or notes allowed.",
      );
    const action = String(d.action),
      now = new Date().toISOString();
    if (action === "approve" && !d.explicitApproval)
      throw new AppError(
        "APPROVAL_REQUIRED",
        "Verification requires explicit user approval.",
      );
    if (action === "promote") {
      if (m.status !== "verified" || !d.sharingApproval)
        throw new AppError(
          "SHARING_APPROVAL_REQUIRED",
          "Verified knowledge and explicit cross-project sharing approval required.",
        );
      // Global knowledge has independent lifecycle and no private source IDs, paths or relations.
      const old = this.db
        .prepare("SELECT id FROM memories WHERE scope='global' AND hash=?")
        .get(String(m.hash));
      if (!old) {
        const gid = randomUUID();
        this.db
          .prepare(
            "INSERT INTO memories(id,project_id,scope,type,content,hash,status,origin,source,version,created,updated) VALUES(?,NULL,'global',?,?,?,'verified','user',?,1,?,?)",
          )
          .run(
            gid,
            String(m.type),
            String(m.content),
            String(m.hash),
            JSON.stringify({
              kind: "user approval",
              reference: "explicit sharing approval; source withheld",
            }),
            now,
            now,
          );
        this.snapshot(gid);
      }
    }
    if (action === "relate" || action === "supersede") {
      if (!d.relatedId || d.relatedId === id)
        throw new AppError(
          "INVALID_RELATION",
          "A different related memory is required.",
        );
      this.memory(p, String(d.relatedId));
      this.db
        .prepare("INSERT OR IGNORE INTO relations VALUES(?,?,?)")
        .run(id, String(d.relatedId), action);
    }
    const status = nextStatus(
      action,
      String(m.status),
      Boolean(d.explicitApproval),
    );
    this.db
      .prepare(
        "UPDATE memories SET status=?,version=version+1,updated=? WHERE id=?",
      )
      .run(status, now, id);
    this.db
      .prepare("INSERT INTO feedback VALUES(?,?,?,?,?)")
      .run(randomUUID(), id, action, String(d.note), now);
    this.snapshot(id);
    return this.view(this.managedMemory(p, id, d));
  });

import { AppError } from "../security/index.js";
export function nextStatus(
  action: string,
  current: string,
  explicitApproval: boolean,
): string {
  if (action === "approve" && !explicitApproval)
    throw new AppError(
      "APPROVAL_REQUIRED",
      "Verification requires explicit user approval.",
    );
  if (action === "approve") return "verified";
  if (action === "reject") return "rejected";
  if (action === "deprecate" || action === "supersede") return "deprecated";
  return current;
}

export class FtsRetriever implements Retriever {
  constructor(private db: DatabaseSync) {}
  search(filter: RetrievalFilter) {
    const words = filter.query.match(/[\p{L}\p{N}_]+/gu)?.slice(0, 40) ?? [];
    if (!words.length) return [];
    const args: SQLInputValue[] = [
      filter.projectId,
      Number(filter.includeGlobal),
    ];
    let where =
      "(m.project_id=? OR (?=1 AND m.scope='global' AND m.status='verified'))";
    for (const field of ["type", "status", "scope"] as const)
      if (filter[field]) {
        where += ` AND m.${field}=?`;
        args.push(filter[field]);
      }
    if (!filter.status) where += " AND m.status IN ('candidate','verified')";
    return this.db
      .prepare(
        `SELECT m.* FROM memory_fts JOIN memories m ON m.id=memory_fts.id WHERE ${where} AND memory_fts MATCH ? ORDER BY bm25(memory_fts),(m.scope='project') DESC,m.id LIMIT ?`,
      )
      .all(...args, words.map((w) => '"' + w + '"').join(" OR "), filter.limit);
  }
}

export function failure(e: unknown) {
  // Keep local exception text and paths private, but retain bounded machine
  // codes so CI and callers can distinguish I/O and SQLite failures.
  const local =
    e instanceof Error
      ? (e as NodeJS.ErrnoException & { errcode?: number })
      : undefined;
  const causeCode =
    !(e instanceof AppError) &&
    typeof local?.code === "string" &&
    /^(?:E[A-Z0-9_]{1,63}|SQLITE_[A-Z_]{1,63})$/.test(local.code)
      ? local.code
      : undefined;
  return {
    ok: false as const,
    error: {
      code: e instanceof AppError ? e.code : "INVALID_REQUEST",
      message:
        e instanceof AppError
          ? e.message
          : "Invalid request or local operation failed.",
      ...(causeCode ? { causeCode } : {}),
      ...(causeCode === "ERR_SQLITE_ERROR" &&
      Number.isSafeInteger(local?.errcode)
        ? { sqliteCode: local!.errcode }
        : {}),
    },
  };
}

if (op === "init") return { database: this.storage.path, version: "0.2.0" };
if (op === "project_register") {
  // Native realpath resolves Windows drive and directory casing to filesystem identity.
  const path = realpathSync.native(String(d.path));
  assertSafe(path);
  if (sensitivePath(path))
    throw new AppError("UNSAFE_PATH", "Sensitive project path.");
  if (!statSync(path).isDirectory() || inside(path, this.storage.path))
    throw new AppError(
      "UNSAFE_DB",
      "Project must be a directory outside the database location.",
    );
  // Register only the actual worktree root; otherwise Git could inspect a parent repository.
  const adapter = new GitAdapter(path);
  if (adapter.root() !== path)
    throw new AppError(
      "UNSAFE_PATH",
      "Register the canonical Git worktree root.",
    );
  return this.storage.transaction(() => {
    this.db
      .prepare("INSERT OR IGNORE INTO projects VALUES(?,?,1,?)")
      .run(randomUUID(), path, new Date().toISOString());
    return this.db.prepare("SELECT * FROM projects WHERE path=?").get(path);
  });
}

const full = join(this.path, file);
if (!inside(this.path, full)) {
  skipped++;
  continue;
}
let stat;
try {
  stat = lstatSync(full);
} catch {
  continue;
}
if (!stat.isFile() || stat.isSymbolicLink()) {
  skipped++;
  continue;
}
const canonical = realpathSync.native(full);
if (
  !inside(this.path, canonical) ||
  relative(this.path, canonical).replaceAll("\\", "/") !== file
) {
  skipped++;
  continue;
}

